BEGIN;
CREATE SCHEMA registry_test;CREATE FUNCTION registry_test.assert(ok boolean,msg text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'ASSERT: %',msg;END IF;END $$;GRANT USAGE ON SCHEMA registry_test TO authenticated;GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA registry_test TO authenticated;
INSERT INTO auth.users(id,email) VALUES('2c000000-0000-4000-8000-000000000001','registry@example.invalid');INSERT INTO public.companies(id,nome,created_by) VALUES('1c000000-0000-4000-8000-000000000001','Registry fixture','2c000000-0000-4000-8000-000000000001'),('1c000000-0000-4000-8000-000000000002','Other fixture','2c000000-0000-4000-8000-000000000001');INSERT INTO public.company_members(company_id,user_id,role,maintenance_role,created_by) VALUES('1c000000-0000-4000-8000-000000000001','2c000000-0000-4000-8000-000000000001','administrador','admin_empresa','2c000000-0000-4000-8000-000000000001');
SELECT set_config('request.jwt.claim.sub','2c000000-0000-4000-8000-000000000001',true);SET LOCAL ROLE authenticated;
INSERT INTO public.motoristas(id,company_id,nome,cnh,validade_cnh,telefone,telefone_emergencia,validade_nr20,observacoes) VALUES('2c000000-0000-4000-8000-000000000002','1c000000-0000-4000-8000-000000000001','Registry driver','12345678901','2028-12-31','11987654321','11976543210','2028-01-10','Actual entered notes');

SELECT set_config('registry_test.claim',public.driver_toxicology_request('1c000000-0000-4000-8000-000000000001','claim','{"id":"2c000000-0000-4000-8000-000000000002","request_id":"6c000000-0000-4000-8000-000000000001"}')::text,true);
SELECT registry_test.assert(current_setting('registry_test.claim')::jsonb->>'phone'='5511987654321','recipient comes from registered phone');
SELECT registry_test.assert(current_setting('registry_test.claim')::jsonb->>'text' LIKE '%exame toxicológico%' AND current_setting('registry_test.claim')::jsonb->>'text' NOT LIKE '%MOPP%' AND current_setting('registry_test.claim')::jsonb->>'text' NOT LIKE '%NR-%','only toxicology requested');
SELECT registry_test.assert(public.driver_toxicology_request('1c000000-0000-4000-8000-000000000001','claim','{"id":"2c000000-0000-4000-8000-000000000002","request_id":"6c000000-0000-4000-8000-000000000001"}')->>'status'='sending','same request cannot claim twice');
SELECT registry_test.assert(public.driver_toxicology_request('1c000000-0000-4000-8000-000000000001','claim','{"id":"2c000000-0000-4000-8000-000000000002","request_id":"6c000000-0000-4000-8000-000000000002"}')->>'status'='sending','concurrent request cannot send twice');
SELECT public.driver_toxicology_request('1c000000-0000-4000-8000-000000000001','finish',jsonb_build_object('id','2c000000-0000-4000-8000-000000000002','request_id','6c000000-0000-4000-8000-000000000001','token',current_setting('registry_test.claim')::jsonb->>'token','status','accepted','message_id','fixture-message'));
SELECT registry_test.assert(public.driver_toxicology_request('1c000000-0000-4000-8000-000000000001','claim','{"id":"2c000000-0000-4000-8000-000000000002","request_id":"6c000000-0000-4000-8000-000000000001"}')->>'status'='accepted','accepted request never sends again');
DO $$ BEGIN BEGIN PERFORM public.driver_toxicology_request('1c000000-0000-4000-8000-000000000002','claim','{"id":"2c000000-0000-4000-8000-000000000002","request_id":"6c000000-0000-4000-8000-000000000003"}');RAISE EXCEPTION 'Tenant isolation failed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END $$;
SELECT registry_test.assert((SELECT count(*)=0 FROM public.driver_toxicology_requests WHERE company_id='1c000000-0000-4000-8000-000000000002'),'tenant rows hidden');
DO $$ BEGIN BEGIN UPDATE public.driver_toxicology_requests SET status='accepted';RAISE EXCEPTION 'Direct write unexpectedly allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END $$;
SELECT set_config('registry_test.claim2',public.driver_toxicology_request('1c000000-0000-4000-8000-000000000001','claim','{"id":"2c000000-0000-4000-8000-000000000002","request_id":"6c000000-0000-4000-8000-000000000002"}')::text,true);
SELECT public.driver_toxicology_request('1c000000-0000-4000-8000-000000000001','finish',jsonb_build_object('id','2c000000-0000-4000-8000-000000000002','request_id','6c000000-0000-4000-8000-000000000002','token',current_setting('registry_test.claim2')::jsonb->>'token','status','unknown'));
SELECT registry_test.assert(public.driver_toxicology_request('1c000000-0000-4000-8000-000000000001','claim','{"id":"2c000000-0000-4000-8000-000000000002","request_id":"6c000000-0000-4000-8000-000000000002"}')->>'status'='unknown','uncertain request cannot retry automatically');
SELECT registry_test.assert(public.driver_toxicology_request('1c000000-0000-4000-8000-000000000001','claim','{"id":"2c000000-0000-4000-8000-000000000002","request_id":"6c000000-0000-4000-8000-000000000002","confirm_uncertain":true}')->>'status'='claimed','explicit confirmation can retry');
SELECT registry_test.assert((SELECT attempts=2 FROM public.driver_toxicology_requests WHERE request_id='6c000000-0000-4000-8000-000000000002'),'retry is audited');
RESET ROLE;ROLLBACK;
